const raw = $input.first()?.json || {};
let ws = {};

if (typeof raw.data === 'string') {
  try {
    const arr = JSON.parse(raw.data);
    if (Array.isArray(arr) && arr.length > 0) ws = arr[0];
  } catch(e) {}
} else if (raw.id) {
  ws = raw;
}

// Safely get lead from whichever normalize node actually ran
let lead = {};
const nodeNames = ['Normalize: Form', 'Normalize: Gmail', 'Normalize: Retell'];
for (const nn of nodeNames) {
  try {
    const item = $(nn).first();
    if (item && item.json && (item.json.email || item.json.source)) {
      lead = item.json;
      break;
    }
  } catch(e) {
    // Node didn't run on this path — skip it
    continue;
  }
}

// Guard: fail loudly if no workspace resolved
if (!ws.id) {
  const token = lead.workspace_token || 'unknown';
  return [{ json: { __error: true, error_reason: `No workspace found for token: "${token}"`, ...lead } }];
}

return [{
  json: {
    ...lead,
    workspace_id: ws.id || null,
    owner_user_id: ws.owner_user_id || null,
    owner_email: ws.owner_email || '',
    notification_email: ws.notification_email || ws.owner_email || '',
    calendly_link: ws.calendly_link || '',
    reply_from_name: ws.reply_from_name || 'Maya',
    workspace_name: ws.name || ''
  }
}];
